lemma logBarrier_le {E : Type u18} {q : E → ℝ} {f : E → ℂ} {δ : ℝ}
    (hδ0 : 0 ≤ δ) (hδ1 : δ ≤ 1) {x : E} (hq : 0 ≤ q x) :
    logBarrier q f δ x ≤ q x + ‖f x‖

lemma logBarrier_tendsto_of_ne_zero {E : Type u19} {q : E → ℝ} {f : E → ℂ}
    {δ : ℕ → ℝ} (hδ : Tendsto δ atTop (𝓝 0)) {x : E}
    (hf : f x ≠ 0) (hq : 0 ≤ q x) :
