lemma translation_average_tendsto {q : ℂ × V → ℝ} {c : ℂ × V} {r : ℝ}
    (hr : 0 < r) (hq : ContinuousOn q (ball c r)) {x : ℂ × V}
    (hx : x ∈ ball c (r / 2)) :
    Tendsto (fun n : ℕ ↦ ∫ a : unitInterval,
      q (x.1 + ((r / (4 * ((n : ℝ) + 1)) : ℝ) : ℂ) * (a : ℝ), x.2))
      atTop (𝓝 (q x))

