    (h : ∀ v : FiberCoordinates, ‖v‖≤1 → quadraticValue H v≤C) (v : FiberCoordinates) :
    quadraticValue H v ≤ C*‖v‖^2

lemma norm_coefficients_of_quadratic_bound {H : TwoMatrix} (hH : H.PosSemidef) {C : ℝ}
