lemma delta_cocycle (q : Chart → Fin r → BasePolynomial) (i j k : Chart) {z : BaseCoordinates}
    (hj : z∈coordinateOverlap i j) (hk : z∈coordinateOverlap i k) :
    B.delta q i j z+(B.matrix i j z).mulVec (B.delta q j k (coordinateChange i j z))=B.delta q i k z

lemma complex_weak_implies_real {u : ℕ → E} {w : E}
    (hw : ∀ v, Tendsto (fun k ↦ inner ℂ (u k) v) atTop (𝓝 (inner ℂ w v))) :
    ∀ v, Tendsto (fun k ↦ inner ℝ (u k) v) atTop (𝓝 (inner ℝ w v))

lemma real_weakLimit_map (A : E →L[ℝ] F) {u : ℕ → E} {w : E}
    (hw : ∀ v, Tendsto (fun k ↦ inner ℝ (u k) v) atTop (𝓝 (inner ℝ w v))) :
    ∀ v, Tendsto (fun k ↦ inner ℝ (A (u k)) v) atTop (𝓝 (inner ℝ (A w) v))

lemma map_restrict_involution_le {T : X → X} {K : Set X} {C : ℝ}
    (hT : Measurable T) (hi : Function.Involutive T)
    (hTK : MeasurableSet (T '' K)) {T' : X → X →L[ℝ] X}
    (hd : ∀ x ∈ T '' K, HasFDerivWithinAt T (T' x) (T '' K) x)
    (hb : ∀ x ∈ T '' K, |(T' x).det| ≤ C) :
    Measure.map T (μ.restrict K) ≤ ENNReal.ofReal C • μ

lemma coordinateChange_compact_bound (i j : StandardChart) {K : Set BaseCoordinates}
    (hK : IsCompact K) (hKU : K ⊆ coordinateOverlap i j) :
    ∃ C : ℝ, 0≤C ∧ Measure.map (coordinateChange i j) (volume.restrict K) ≤ ENNReal.ofReal C • volume

lemma weak_coefficients_positive {α : Type u26} {n : Type u27} [MeasurableSpace α]
    [Fintype n] [DecidableEq n] {μ : Measure α}
    {f : ℕ → Lp (EuclideanSpace ℂ (n × n)) 2 μ}
    {w : Lp (EuclideanSpace ℂ (n × n)) 2 μ}
    (hf : ∀ m, ∀ᵐ x ∂μ, (coefficientsToMatrix (f m x)).PosSemidef)
    (hw : ∀ v, Tendsto (fun m ↦ inner ℂ (f m) v) atTop (𝓝 (inner ℂ w v))) :
    ∀ᵐ x ∂μ, (coefficientsToMatrix (w x)).PosSemidef

lemma weak_quadratic_averages {n : Type u29} [Fintype n]
    {f : ℕ → Lp (EuclideanSpace ℂ (n × n)) 2 (volume : Measure (ℂ × ℂ))}
    {w : Lp (EuclideanSpace ℂ (n × n)) 2 (volume : Measure (ℂ × ℂ))}
    {Hm : ℕ → (ℂ × ℂ) → Matrix n n ℂ}
    (hf : ∀ m, (fun x ↦ coefficientsToMatrix (f m x)) =ᵐ[volume] Hm m)
    (hw : ∀ v, Tendsto (fun m ↦ inner ℂ (f m) v) atTop (𝓝 (inner ℂ w v)))
    (x : ℂ × ℂ) (r : ℝ) (v : n → ℂ) :
    Tendsto (fun m ↦ ⨍ y in ball x r, quadraticValue (Hm m y) v) atTop
      (𝓝 (⨍ y in ball x r, quadraticValue (coefficientsToMatrix (w y)) v))

theorem euclidean_eq_halfspaces [DecidableEq ι] (c : ℝ) (hc : 0 < c) :
    (euclidean c : Set (EuclideanSpace ℝ ι)) =
      {x | ∀ u : EuclideanSpace ℝ ι, ⟪u, x⟫ ≤ c * support (WithLp.ofLp u)}

@[simp] lemma label_tail (b : Bool) (f : GridDisk.Face H (3*K)) (i : Fin 3) :
    label H K u v hv ((mesh H K).tail ((b,f),i)) =
      if b then v (GridDisk.tail H (3*K) (f,i)) else u (GridDisk.tail H (3*K) (f,i))

