lemma TargetLegal_translate (b : TriangleGroup) {v : Fin 3 → TriangleGroup}
    (h : ∃ t : TargetTriangle, ∀ k, ∃ j, t.vertex j = v k) :
    ∃ t : TargetTriangle, ∀ k, ∃ j, t.vertex j = b*v k

lemma circle_lipschitz {R : ℝ} (hR0 : 0≤R) (i : Fin 6) {s t : ℝ}
    (hs : s∈Set.Icc 0 1) (ht : t∈Set.Icc 0 1) :
    dist (circle y R i s • y) (circle y R i t • y) ≤ 20*R*|s-t|+C

lemma product_next {N : ℕ} [NeZero N] (a : Fin 6) (j : Fin N) :
    finProdFinEquiv (a,j)+1 =
      if h : j.val+1<N then finProdFinEquiv (a,⟨j.val+1,h⟩)
      else finProdFinEquiv (a+1,0)

lemma segment_isometry {Z : Type*} [MetricSpace Z] {x y : X} {γ : ℝ → X}
    (h : Segment x y γ) {f : X → Z} (hf : Isometry f) :
    Segment (f x) (f y) (f ∘ γ)

lemma comparison_common_start (hX : CAT0 X) {x y z : X} {γ η : ℝ → X}
    (hγ : Segment x y γ) (hη : Segment x z η) {t : ℝ} (ht : t ∈ Set.Icc 0 1) :
    dist (γ t) (η t) ≤ t * dist y z

lemma segment_unique (hX : CAT0 X) {x y : X} {γ η : ℝ → X}
    (hγ : Segment x y γ) (hη : Segment x y η) {t : ℝ} (ht : t ∈ Set.Icc 0 1) :
    γ t = η t

lemma comparison_convexity (hX : CAT0 X) {a b c d : X} {γ η : ℝ → X}
    (hγ : Segment a b γ) (hη : Segment c d η) {t : ℝ} (ht : t ∈ Set.Icc 0 1) :
    dist (γ t) (η t) ≤ (1 - t) * dist a c + t * dist b d

lemma midpoint_comparison (hX : CAT0 X) (z : X) {x y : X} {γ : ℝ → X}
    (hγ : Segment x y γ) :
    dist z (γ (1 / 2)) ^ 2 ≤ (dist z x ^ 2 + dist z y ^ 2) / 2 - dist x y ^ 2 / 4

lemma face_local {p : Fin 3 → Point} (hp : face p ≠ 0) (x : Point) {ε : ℝ}
    (hx : ∀ i, |(p i).1 - x.1| < ε ∧ |(p i).2 - x.2| < ε) :
    |x.1| < ε ∧ |x.2| < ε

lemma step_strip {g : TriangleGroup} {p q : List TriangleGroup}
    (hs : PathStep p q) (hp : GoodPath g p) (hn : p.length ≤ N) :
    Strip (padded g p : Row N) (padded g q)

lemma commuting_minimizer (hG : GeometricAction G X) (y : X) {g h : G}
    (hc : Commute g h) : ∃ x : X,
      dist x (g • x) = stableLengthAt y g ∧ dist x (h • x) = stableLengthAt y h

theorem commuting_orbit_uniform (hG : GeometricAction G X) (y : X) {g h : G}
    (hc : Commute g h) : ∃ C : ℝ, 0 ≤ C ∧ ∀ i j : ℤ,
      |dist y ((g^i*h^j) • y) - stableLengthAt y (g^i*h^j)| ≤ C

lemma deletions_grid {g : TriangleGroup} {p q : List TriangleGroup}
    (h : ReflTransGen PathStep p q) (hp : GoodPath g p) (hn : p.length ≤ N) :
    ReflTransGen Strip (padded g p : Row N) (padded g q)

theorem rawWord_nullhomotopic {a : Quiver.Symmetrify d.Vertex}
    (p : Quiver.Path a a) (h : d.wordValue (d.rawWord p) = 1) :
    d.RawHomotopic p (𝟙 (d.rawVertex a))

theorem WordPath.exists_raw {a c : d.Vertex} {w : List d.OrientedEdge}
    (h : Release075.WordPath d.flipEdge d.edgeTarget a c w) :
    ∃ p : (d.rawVertex a ⟶ d.rawVertex c), d.rawWord p = w

theorem WordPath.forget {x y : d.LiftedVertex} {w : List d.LiftedEdge}
    (hw : WordPath d.liftedFlip d.liftedTarget x y w) :
    WordPath d.flipEdge d.edgeTarget x.1 y.1 (w.map Prod.fst)

theorem WordPath.displacement {x y : d.LiftedVertex} {w : List d.LiftedEdge}
    (hw : WordPath d.liftedFlip d.liftedTarget x y w) :
    x.2 * d.wordValue (w.map Prod.fst) = y.2

theorem WordPath.liftWord_eq {x y : d.LiftedVertex} {w : List d.LiftedEdge}
    (hw : WordPath d.liftedFlip d.liftedTarget x y w) :
    d.liftWord x.2 (w.map Prod.fst) = w

theorem lifted_closed_fillable {x : d.LiftedVertex} {w : List d.LiftedEdge}
    (hw : WordPath d.liftedFlip d.liftedTarget x x w) :
    Fillable d.liftedFlip d.liftedTarget d.LiftedFace w

theorem boundary₁_wordChain {x y : d.LiftedVertex} {w : List d.LiftedEdge}
    (hw : WordPath d.liftedFlip d.liftedTarget x y w) :
    d.boundary₁ (d.wordChain w) = Finsupp.single y 1 - Finsupp.single x 1

theorem powerWord_typed (g : d.GroupType) {w : List d.LiftedEdge}
    (hw : WordPath d.liftedFlip d.liftedTarget (.o,1) (.o,g) w) (n : ℕ) :
    WordPath d.liftedFlip d.liftedTarget (.o,1) (.o,g^n) (d.powerWord g w n)

theorem powerWord_shift_rotate (g : d.GroupType) (w : List d.LiftedEdge) {n : ℕ}
    (hn : 0 < n) (hg : g^n = 1) :
    (d.powerWord g w n).map (d.shiftEdge g) = (d.powerWord g w n).rotate w.length

theorem liftedForm_loop_bound {x : (d.presentation hr).LiftedVertex}
    {w : List (d.presentation hr).LiftedEdge}
    (hw : WordPath (d.presentation hr).liftedFlip (d.presentation hr).liftedTarget x x w)
    (o a : (d.presentation hr).GroupType) (T : ℕ) :
    |(w.map ((d.presentation hr).liftedForm o a T)).sum| ≤ 38*w.length

theorem triple_diskChain {w : List d.LiftedEdge}
    (D : TriangleFilling d.liftedFlip d.liftedTarget d.LiftedFace w) :
    3 • d.diskChain D = -D.full.trace d.faceEval

theorem boundary₂_diskChain {w : List d.LiftedEdge}
    (D : TriangleFilling d.liftedFlip d.liftedTarget d.LiftedFace w) :
    d.boundary₂ (d.diskChain D) = d.wordChain w

theorem diskChain_unique {w : List (d.presentation hr).LiftedEdge}
    {x : (d.presentation hr).LiftedVertex}
    (hw : WordPath (d.presentation hr).liftedFlip (d.presentation hr).liftedTarget x x w)
    (D D' : TriangleFilling (d.presentation hr).liftedFlip (d.presentation hr).liftedTarget
      (d.presentation hr).LiftedFace w) :
    (d.presentation hr).diskChain D = (d.presentation hr).diskChain D'

theorem synchronous_of_near {p : Path M a b} {s : Path M a c}
    (hp : p.Geodesic) (hs : s.Geodesic) {i j T : ℕ}
    (hi : i ≤ p.length) (hi' : i ≤ s.length) (hj : j ≤ s.length)
    (h : M.dist (p.point i) (s.point j) ≤ T) :
    M.dist (p.point i) (s.point i) ≤ 2*T

theorem synchronous {p : Path M a b} {q : Path M b c} {s : Path M a c}
    (hp : p.Geodesic) (hq : q.Geodesic) (hs : s.Geodesic) {T i : ℕ}
    (hthin : SideNear T p q s) (hi : i ≤ (p.length+s.length-q.length)/2) :
    M.dist (p.point i) (s.point i) ≤ 4*T+2

theorem integral_form_quadratic (p : Path M a b) (hp : p.Geodesic) {t T : ℕ}
    (ht : t ≤ p.length) (hend : T ≤ M.dist (p.point t) b) :
    ((T/2:ℕ):ℤ)^2 ≤ p.integral (M.form (p.point t) a T)

theorem shortBypass_quadratic {B T K : ℕ} {o : V}
    (hB : CochainBound M B) (h : ShortBypass M T o K) :
    ((T/2:ℕ):ℤ)^2 ≤ (B:ℤ)*K

theorem fullChain_unique {w : List (d.presentation hr).LiftedEdge}
