lemma kernel_mul_sum {K L : Matrix ι ι ℝ}
    (hK : ∀ x, ∑ y, K x y = 1) (hL : ∀ x, ∑ y, L x y = 1) (x : ι) :
    ∑ y, (K * L) x y = 1

lemma kernel_pow_stationary {K : Matrix ι ι ℝ} {μ : ι → ℝ}
    (hK : ∀ y, ∑ x, μ x * K x y = μ y) (k : ℕ) (y : ι) :
    ∑ x, μ x * (K ^ k) x y = μ y

lemma poisson_kernel_stationary {P : Matrix ι ι ℝ} {μ : ι → ℝ}
    (hP : ∀ y, ∑ x, μ x * P x y = μ y) (a : ℝ) (y : ι) :
    ∑ x, μ x * NormedSpace.exp (a • (P - 1)) x y = μ y

lemma correlatedVector_gram {u v : EuclideanSpace ℝ ι} {r t : ℝ}
    (hu : ‖u‖ = r) (hv : ‖v‖ = r) (horth : inner ℝ u v = 0) (ht : |t| ≤ 1) :
    ‖correlatedVector u v t‖ = r ∧ inner ℝ u (correlatedVector u v t) = t*r^2

lemma correlatedMoment_sign (lam : ι → ℝ) {u v : EuclideanSpace ℝ ι}
    (horth : inner ℝ u v = 0) (q t : ℝ) :
    pairMoment lam u (correlatedVector u (-v) t) q = pairMoment lam u (correlatedVector u v t) q

lemma pairMoment_correlated_lower (lam : ι → ℝ) {u v : EuclideanSpace ℝ ι}
    (hnorm : ‖u‖ = ‖v‖) (horth : inner ℝ u v = 0) {q t : ℝ}
    (hq : q ∈ Set.Icc 0 1) (ht : |t| ≤ 1) :
    pairMoment lam u v q ≤ pairMoment lam u (correlatedVector u v t) q

lemma pairMoment_le_partition_product (lam : ι → ℝ) {u v : EuclideanSpace ℝ ι} {r q : ℝ}
    (hu : ‖u‖ = r) (hv : ‖v‖ = r) (horth : inner ℝ u v = 0) (hq : q ∈ Set.Icc 0 1) :
    pairMoment lam u v q ≤ spherePartition lam (1+q) r * spherePartition lam (1-q) r

lemma sphericalVariational_deriv_integrable (lam : ι → ℝ) {a b C : ℝ}
    (hlam : ∀ i, |lam i| ≤ C) (ha : 0 ≤ a) (hab : a ≤ b) :
    IntervalIntegrable (deriv (sphericalVariational lam)) volume a b

lemma pairMoment_mono_abs (lam : ι → ℝ) {x y : EuclideanSpace ℝ ι}
    (hxy : ‖x‖ = ‖y‖) {q r : ℝ} (hqr : |q| ≤ |r|) :
    pairMoment lam x y q ≤ pairMoment lam x y r

lemma sphereOverlap_second_moment (lam : ι → ℝ) {u v : EuclideanSpace ℝ ι} {r : ℝ}
    (hu : ‖u‖ = r) (hv : ‖v‖ = r) (horth : inner ℝ u v = 0) :
    (∫ q, pairMoment lam u v q ∂sphereOverlapLaw ι) = (spherePartition lam 1 r)^2

