    (hf : Integrable f μ) (hfn : ∀ x, 0 ≤ f x) {A : Set (sphere (0 : E) 1)}
    (hA : MeasurableSet A) {a b : ℝ} (ha : 0 ≤ a) :
    (μ.withDensity (fun x => ENNReal.ofReal (f x)) (normShell a b ∩ radialCone A)).toReal =
