theorem tailError_bound {f : ℕ → α → ℝ} {g F : α → ℝ}
    (hf : ∀ n x, |f n x| ≤ F x) (hg : ∀ x, |g x| ≤ F x) (N : ℕ) (x : α) :
    tailError f g N x ≤ 2*F x

