    (hf : ∀ n x, |f n x| ≤ F x) (hg : ∀ x, |g x| ≤ F x) {N k : ℕ}
    (hk : N ≤ k) (x : α) : |f k x - g x| ≤ tailError f g N x

theorem tailError_nonneg {f : ℕ → α → ℝ} {g F : α → ℝ}
    (hf : ∀ n x, |f n x| ≤ F x) (hg : ∀ x, |g x| ≤ F x) (N : ℕ) (x : α) :
    0 ≤ tailError f g N x

